begin;
create extension if not exists pgtap with schema extensions;
select plan(19);
insert into auth.users(id,email,raw_user_meta_data) values('a7000000-0000-4000-8000-000000000001','notification-owner@example.test','{}'),('a7000000-0000-4000-8000-000000000002','notification-other@example.test','{}');
insert into public.subscriptions(user_id,status) values('a7000000-0000-4000-8000-000000000001','active');
insert into public.estimates(id,user_id,client_name,client_email) values('b7000000-0000-4000-8000-000000000001','a7000000-0000-4000-8000-000000000001','Fixture','customer@example.test');
select ok(not has_table_privilege('authenticated','public.notification_outbox','SELECT,INSERT,UPDATE,DELETE'),'outbox is not accessible to browsers');
select ok(not has_function_privilege('authenticated','public.workcraft_claim_notifications(integer,uuid[])','EXECUTE'),'only server can claim notifications');
select ok(not has_function_privilege('anon','public.workcraft_record_email_delivery(text,text,text)','EXECUTE'),'only signed server handler can record deliveries');
insert into public.proposal_questions(id,user_id,estimate_id,customer_name,customer_email,message) values('c7000000-0000-4000-8000-000000000001','a7000000-0000-4000-8000-000000000001','b7000000-0000-4000-8000-000000000001','Customer','customer@example.test','Question');
select is((select count(*) from public.notification_outbox where send_key='proposal-question-c7000000-0000-4000-8000-000000000001'),1::bigint,'saving a question atomically queues its mail');
set local role service_role;
select is((select count(*) from public.workcraft_claim_notifications(4,null)),1::bigint,'due notification is claimed once');
select is((select count(*) from public.workcraft_claim_notifications(4,null)),0::bigint,'active lease prevents concurrent delivery');
update public.notification_outbox set lease_until=now()-interval '1 minute';
select is((select count(*) from public.workcraft_claim_notifications(4,null)),1::bigint,'expired lease can be recovered');
select is(public.workcraft_record_email_delivery('event-before-send','mail-fixture','delivered'),true,'delivery before send is retained');
select is(public.workcraft_finish_notification((select id from public.notification_outbox limit 1),'mail-fixture','customer@example.test'),true,'successful send is committed');
select is((select count(*) from public.transactional_email_events where provider_email_id='mail-fixture'),2::bigint,'early delivery is correlated after send');
select is(public.workcraft_finish_notification((select id from public.notification_outbox limit 1),'mail-fixture','customer@example.test'),true,'repeated completion is harmless');
select is((select count(*) from public.transactional_email_events where provider_email_id='mail-fixture'),2::bigint,'no duplicate sent or delivery rows');
select is((select payload from public.notification_outbox limit 1),'{}'::jsonb,'message payload is scrubbed after send');
select is((select count(*) from public.workcraft_claim_notifications(4,null)),0::bigint,'sent mail cannot be reclaimed');
insert into public.provider_email_daily_usage(usage_date,source,emails_started) values((now() at time zone 'UTC')::date,'app',75),((now() at time zone 'UTC')::date,'auth',19),((now() at time zone 'UTC')::date,'billing',4) on conflict(usage_date,source) do update set emails_started=excluded.emails_started;
select is((select reason from public.workcraft_reserve_app_email('support')),'platform_daily_limit','app pool stops at 75');
select is((select reason from public.workcraft_reserve_app_email('auth','a7000000-0000-4000-8000-000000000001')),'allowed','app exhaustion does not consume Auth reserve');
select is((select reason from public.workcraft_reserve_app_email('auth','a7000000-0000-4000-8000-000000000001')),'platform_daily_limit','Auth stops at 20');
select is((select reason from public.workcraft_reserve_app_email('billing','a7000000-0000-4000-8000-000000000001')),'allowed','billing reserve remains independent');
select is((select reason from public.workcraft_reserve_app_email('billing','a7000000-0000-4000-8000-000000000001')),'platform_daily_limit','billing stops at 5');
select * from finish();rollback;
